        let ctx = canvas.getContext("2d");
        let canvasWidth = canvas.width;
        let canvasHeight = canvas.height;
        let pendulumLength = 100;
        let initialAngle = 45;
        let gravity = 0.1;
        let initialVelocity = 0;
        let isReleased = false;
        let angle = 0;
        let velocity = 0;
        let time = 0;

        canvas.addEventListener("mousedown", mouseDownEvent);
        document.getElementById("release-button").addEventListener("click", releasePendulum);

        function mouseDownEvent(e) {
            if (!isReleased) {
                initialAngle = e.offsetY / canvasHeight * Math.PI * 2;
                initialVelocity = 0;
                isReleased = true;
            }
        }

        function releasePendulum() {
            isReleased = true;
        }

        function update() {
            angle += velocity;
            velocity += (-gravity * Math.sin(angle)) / pendulumLength;
            time += 0.1;

            ctx.clearRect(0, 0, canvasWidth, canvasHeight);
            ctx.beginPath();
            ctx.arc(canvasWidth / 2, canvasHeight / 2, pendulumLength, Math.PI - initialAngle, Math.PI - initialAngle - angle, false);
            ctx.stroke();

            if (Math.abs(velocity) < 0.01 && angle > Math.PI/180 * 0.1) {
                isReleased = false;
            }

            requestAnimationFrame(update);
        }

        update();
    </script>
