#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  pineSetup();

  // Set pin 12 as an output
  gpioSetup(12, Pine::OUTPUT);

  // Set the initial state of pin 12 to LOW (0V)
  gpioWrite(12, 0);

  // Main loop
  while (1) {
    // Toggle the state of pin 12 every 1 second
    gpioWrite(12, gpioRead(12) ? 0 : 1);
    delay(1000); // 1 second delay
  }

  // Clean up
  gpioCleanup();
  return 0;
}
```
